shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-dark: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --crimson: #8f2424;
    --crimson-soft: rgba(143, 36, 36, 0.1);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --gold: #c99a49;
    --font-serif-cn: 'Noto Serif SC', serif;
    --font-sans-cn: 'Noto Sans SC', sans-serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', serif;
    --font-mono: 'JetBrains Mono', monospace;
    --font-ui: 'Inter', 'Noto Sans SC', sans-serif;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    font-family: var(--font-serif-cn);
    overflow-x: hidden;
    line-height: 1.8;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.72;
  }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.06);
    z-index: 1001;
  }
  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .wsj-brand {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }
  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }
  .wsj-divider {
    width: 1px;
    height: 16px;
    background: var(--line-dark);
  }
  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
  }
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-ui);
    font-size: 0.76rem;
    font-weight: 600;
    padding: 0.3rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--line);
  }
  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--crimson);
    font-weight: 700;
  }
  .kicker-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--crimson);
    display: inline-block;
  }
  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(2.1rem, 4.4vw, 3.6rem);
    font-weight: 800;
    line-height: 1.18;
    color: var(--ink);
    max-width: 960px;
    margin-bottom: 1.25rem;
    letter-spacing: -0.015em;
  }
  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.26;
    letter-spacing: 0.01em;
  }
  .hero-dek {
    font-size: clamp(1.12rem, 1.8vw, 1.38rem);
    line-height: 1.6;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }
  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-ui);
    font-size: 0.82rem;
    color: var(--muted);
  }
  .byline-name {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }
  .dateline-tag {
    font-family: var(--font-mono);
    font-size: 0.76rem;
    color: var(--muted);
  }

  /* Strategic Dossier Strip (Context + Opening Overview) */
  .dossier-strip {
    max-width: 1180px;
    margin: 2rem auto 0;
    padding: 0 1.5rem;
  }
  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-left: 4px solid var(--accent);
    padding: 1.35rem 1.6rem;
    display: grid;
    grid-template-columns: 200px 1fr;
    gap: 1.5rem;
    align-items: start;
  }
  .dossier-label {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    font-weight: 700;
    line-height: 1.5;
  }
  .dossier-label span {
    display: block;
    color: var(--muted);
    font-weight: 400;
    margin-top: 0.25rem;
    font-size: 0.7rem;
  }
  .dossier-text {
    font-family: var(--font-sans-cn);
    font-size: 0.94rem;
    line-height: 1.7;
    color: var(--body);
  }

  /* Main Editorial Grid */
  .editorial-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
  }

  .chapter-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 360px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .sidebar-col {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Typography */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.5rem;
  }
  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.78;
  }

  .lead-p {
    font-size: 1.24rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 600;
    padding-left: 1.15rem;
    border-left: 3px solid var(--accent);
    margin-bottom: 1.75rem;
  }
  :host([lang="en"]) .lead-p {
    font-size: 1.2rem;
    font-weight: 400;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Chapter Headers */
  .chapter-divider {
    margin: 3.25rem 0 2rem;
    padding-top: 2rem;
    border-top: 2px solid var(--ink);
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
  }
  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .chapter-title {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
  }

  /* Incident Forensic Card (p3-p5) */
  .forensic-incident-box {
    background: #f6f1e9;
    border: 1px solid var(--line-dark);
    border-top: 3px solid var(--crimson);
    padding: 1.6rem 1.75rem;
    margin: 2rem 0;
  }
  .forensic-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--line-dark);
    padding-bottom: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--crimson);
    font-weight: 700;
  }
  .forensic-incident-box .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Side Rail Cards */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 1.4rem;
  }
  .rail-card-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.65rem;
    display: block;
  }
  .rail-card-title {
    font-family: var(--font-display);
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.35;
  }

  /* Derived Metric Cards */
  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-top: 3px solid var(--ink);
    padding: 1.4rem;
  }
  .metric-val {
    font-family: var(--font-display);
    font-size: 2.3rem;
    font-weight: 800;
    color: var(--accent);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }
  .metric-lbl {
    font-family: var(--font-ui);
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--ink);
    margin-bottom: 0.5rem;
  }
  .metric-note {
    font-family: var(--font-sans-cn);
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--muted);
  }

  /* Pull Quote */
  .pull-quote {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.75rem 1.6rem;
    border-left: 4px solid var(--gold);
    margin: 0;
  }
  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.18rem;
    line-height: 1.55;
    color: #ffffff;
    margin-bottom: 0.9rem;
  }
  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--gold);
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  /* Full-Bleed Strategic Map & Choke Point Diagram */
  .graphic-breakout {
    margin: 3rem 0;
    background: var(--navy-bg);
    color: var(--paper);
    border: 1px solid #25384d;
    padding: 2rem;
  }
  .graphic-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
    padding-bottom: 1.1rem;
    margin-bottom: 1.5rem;
  }
  .graphic-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 0.35rem;
  }
  .graphic-title {
    font-family: var(--font-display);
    font-size: 1.45rem;
    font-weight: 700;
    color: #fff;
  }
  .graphic-sub {
    font-family: var(--font-ui);
    font-size: 0.86rem;
    color: #b0becf;
    max-width: 640px;
  }
  .graphic-caption {
    margin-top: 1.1rem;
    padding-top: 0.85rem;
    border-top: 1px solid rgba(255, 255, 255, 0.12);
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: #8fa2b8;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Vision 2030 Fiscal Crunch Visual */
  .fiscal-viz-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 1.75rem;
    margin: 2.25rem 0;
  }
  .fiscal-panel-head {
    border-bottom: 1px solid var(--line-dark);
    padding-bottom: 0.9rem;
    margin-bottom: 1.25rem;
  }
  .fiscal-panel-title {
    font-family: var(--font-display);
    font-size: 1.28rem;
    color: var(--ink);
    margin-top: 0.25rem;
  }

  /* Timeline / Escalation Matrix */
  .timeline-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.95rem;
  }
  .timeline-item {
    position: relative;
    padding-left: 1rem;
    border-left: 2px solid var(--line-dark);
  }
  .timeline-item.alert {
    border-left-color: var(--crimson);
  }
  .tl-date {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--accent);
    display: block;
    margin-bottom: 0.15rem;
  }
  .timeline-item.alert .tl-date {
    color: var(--crimson);
  }
  .tl-desc {
    font-family: var(--font-sans-cn);
    font-size: 0.84rem;
    line-height: 1.5;
    color: var(--body);
  }

  /* Footer */
  .ed-footer {
    border-top: 1px solid var(--line-dark);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    margin-top: 3rem;
  }
  .ed-footer-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .chapter-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .dossier-box {
      grid-template-columns: 1fr;
      gap: 0.65rem;
    }
  }

  @media (max-width: 540px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .hero {
      padding: 2.2rem 1rem 1.75rem;
    }
    .dossier-strip {
      padding: 0 1rem;
    }
    .editorial-container {
      padding: 1.75rem 1rem 3rem;
    }
    .graphic-breakout {
      padding: 1.25rem 1rem;
      margin: 2rem 0;
    }
    .forensic-incident-box {
      padding: 1.25rem 1.15rem;
    }
    .chapter-divider {
      flex-direction: column;
      gap: 0.35rem;
    }
  }
